def nar_gold(text):
    """Розмітка шаблонного звіту: NAR, CLM, VRD, PUB, ACC, OFF, Аналітик Ф-xx; відношення PART_OF, REFUTES, SPREADS."""
    ents, rels = [], []
    nar = re.search(r"NAR-\d\d", text).group()
    for code in sorted(set(re.findall(r"\b(?:NAR|CLM|VRD|PUB|ACC|OFF)-\d+\b|Ф-\d\d", text))):
        ents.append((code, "CASE_ID", code))
    for org in OFF.values():
        if org in text: ents.append((org, "ORG", org))
    for surf, city in CITIES:
        if surf in text: ents.append((surf, "LOCATION", city))
    for m in re.finditer(r"Анонімний Telegram-канал #\d", text):
        ents.append((m.group(), "CASE_ID", None))   # псевдонім акаунта; канонічна назва — ACC-код (див. нижче)
    for para in text.split("\n\n"):
        c = re.match(r"(CLM-\d\d): (.+?)\. Пріоритет", para)
        if not c: continue
        clm = c.group(1)
        rels.append((clm, "PART_OF", nar, c.group(0)[:40]))
        o = re.search(r"Спростовано офіційним джерелом (.+?) \((OFF-\d\d)\)", para)
        if o: rels.append((o.group(1), "REFUTES", clm, o.group(0)))
        a = re.search(r"першоджерело: PUB-\d+ від (ACC-\d+) \((Анонімний Telegram-канал #\d)\)", para)
        if a: rels.append((a.group(1), "SPREADS", clm, a.group(0)))
    return ents, rels
